S('0224',"تعليمات التدريب الهندسي لكلية الهندسة",[
("rule",[1],"المادة 3","يشترط أن يكون التدريب الهندسي لدى المؤسسات المعتمدة لدى مجلس القسم من قبل الطلبة داخل وخارج الأردن، والجهات المعتمدة من قبل الايستي.",
 "أين يجري الطالب التدريب الهندسي؟","هل يجوز التدريب في أي مؤسسة؟","وين لازم أتدرب تدريب هندسي؟"),
("number",[1],"المادة 4","يتلقى كل طالب في كلية الهندسة تدريباً عملياً بعد أن ينهي ما لا يقل عن (117) ساعة معتمدة، وتكون مدة التدريب (8) أسابيع، ولا يجوز أن يسجل لأي مساق خلال فترة التدريب في فصل الصيف، باستثناء الطالب المتبقي له على الفصل الصيفي (3) ساعات معتمدة بالإضافة إلى مساق التدريب الهندسي وبموافقة العميد.",
 "كم ساعة معتمدة يجب أن ينهيها طالب الهندسة قبل التدريب الهندسي؟","كم مدة التدريب الهندسي لطالب كلية الهندسة؟","كم أسبوع التدريب الهندسي؟"),
("rule",[1],"المادة 5","تشكل لجنة (منبثقة عن مجلس الكلية) تسمى لجنة التدريب الهندسي لتنسيق عملية التدريب في الكلية تضم مشرف التدريب في كل قسم بالإضافة إلى نائب العميد أو من يفوضه العميد مقرراً لهذه اللجنة، وتكون مهامها: إجراء الاتصالات والمراسلات مع الشركات والمؤسسات ومراكز التدريب لغايات توفير فرص التدريب، والاتفاق مع مسؤولي المؤسسات التي يتدرب فيها الطلاب على تقييم الطلاب المتدربين وتعبئة نموذج التقييم، والنظر في مشكلات التدريب واتخاذ القرارات بخصوصها.",
 "ما مهام لجنة التدريب الهندسي في كلية الهندسة؟","من يتألف منهم لجنة التدريب الهندسي؟","شو بتعمل لجنة التدريب الهندسي؟"),
("rule",[1],"المادة 6 و7","يجوز للطلبة توفير فرص تدريب لأنفسهم داخل أو خارج المملكة، وفي جميع الحالات لا يجوز مباشرة التدريب إلا بعد موافقة المشرف، ولا يجوز تغيير مكان التدرب إلا بموافقة المشرف.",
 "هل يجوز للطالب أن يوفر فرصة تدريب لنفسه؟","هل يجوز تغيير مكان التدريب الهندسي دون موافقة المشرف؟","بقدر ألاقي تدريب لحالي؟"),
("rule",[1],"المادة 11","لا يجوز الغياب أثناء فترة التدريب، وفي الحالات الاضطرارية على الطالب أن يعوض بدل المدة التي تغيبها. ويجب على الطالب الالتزام بدوام المؤسسة المدربة من حيث أوقات وأيام الدوام.",
 "هل يجوز الغياب أثناء فترة التدريب الهندسي؟","ماذا يفعل الطالب إذا تغيب أثناء التدريب لحالة اضطرارية؟","اذا تغيبت يوم بالتدريب شو بصير؟"),
("number",[1],"المادة 12 إلى 15","بعد الانتهاء من التدريب يعد الطالب تقريراً فنياً يبين فيه النشاطات التي قام بها، ويقدم التقرير الفني إلى المشرف خلال فترة لا تتجاوز الشهر من انتهاء فترة التدريب، ويتم اعتماد التدريب الهندسي من قبل مجلس القسم خلال فترة لا تتجاوز الشهر من تاريخ استلام التقارير. ويتحمل الطالب مسؤولية متابعة إجراءات التدريب من حيث التأكد من وصول النماذج من وإلى الجهة المدربة.",
 "خلال كم مدة يقدم الطالب التقرير الفني بعد انتهاء التدريب الهندسي؟","من يعتمد التدريب الهندسي وخلال كم مدة؟","متى لازم أسلم تقرير التدريب؟"),
])

S('0225',"أسس التدريب الميداني في كلية تكنولوجيا الحاسوب والمعلومات",[
("number",[1],"المادة 4 و5","يجب أن يكون التدريب في مكان واحد، على أن يسمح للطالب بعد تنسيب المشرف وموافقة رئيس القسم المعني أن يتدرب في مكانين معتمدين للتدريب على الأكثر بحيث لا تقل مدة التدريب في أي منهما عن نصف فترة التدريب المقررة. ويكون الحد الأدنى لمدة التدريب الميداني اثني عشر أسبوعاً متواصلة وبعدد ساعات دوام فعلي لا تقل عن 300 ساعة.",
 "كم الحد الأدنى لمدة التدريب الميداني في كلية تكنولوجيا الحاسوب والمعلومات؟","هل يجوز التدريب في أكثر من مكان في التدريب الميداني؟","كم أسبوع وكم ساعة التدريب الميداني بكلية الحاسوب؟"),
("number",[1],"المادة 6 و7","يسمح للطلبة المسجلين في مساق التدريب الميداني في الفصل الدراسي الأول والفصل الدراسي الثاني تسجيل (6 ساعات معتمدة) على الأكثر إضافة إلى مساق التدريب، ويسمح للطلبة الخريجين على الفصل الصيفي تسجيل (3 ساعات معتمدة) كحد أعلى مع مساق التدريب.",
 "كم ساعة يسمح بتسجيلها مع مساق التدريب الميداني في الفصل الأول والثاني؟","كم ساعة يسمح للخريج بتسجيلها مع التدريب الميداني في الصيفي؟","كم ساعة بقدر أسجل مع التدريب الميداني؟"),
("rule",[1],"المادة 8 و9 و10","في حالتي المادتين 6 و7 لا تحتسب ساعات الدوام الرسمي في الجامعة من ضمن فترة التدريب، وعلى الطلبة أن يحققوا شرط مدة التدريب من خلال زيادة مدة التدريب لغاية تحقيق شرط عدد الساعات الفعلية. ويتم اعتماد مكان التدريب من قبل شعبة التدريب في الكلية بعد التنسيق مع القسم المعني، وعلى المشرف متابعة الطلبة وزيارتهم في أماكن التدريب مرة واحدة على الأقل.",
 "من يعتمد مكان التدريب الميداني في كلية تكنولوجيا الحاسوب والمعلومات؟","كم مرة يزور المشرف الطالب في مكان التدريب؟","مين بوافق على مكان تدريبي؟"),
],'image')

S('0226',"تعليمات التدريب في جامعة العلوم والتكنولوجيا الأردنية لحملة المؤهلات العلمية",[
("rule",[1],"ثالثاً ورابعاً وخامساً","تهدف التعليمات لتنظيم عملية التدريب في الجامعة لغير العاملين فيها. يقدم طلب التدريب على النموذج المعتمد لدى وحدة الموارد البشرية، ويتم التدريب بموافقة الرئيس بناء على توصية العميد / المدير المعني.",
 "ما الهدف من تعليمات التدريب في الجامعة لحملة المؤهلات العلمية؟","كيف يقدم طلب التدريب في الجامعة لغير العاملين فيها؟","كيف بقدم طلب تدريب بالجامعة؟"),
("number",[1],"سابعاً","تكون مدة التدريب ثلاثة أشهر حد أقصى قابلة للتجديد مرة واحدة وبموافقة الرئيس بناء على تنسيب العميد / المدير.",
 "كم مدة التدريب لحملة المؤهلات العلمية في الجامعة؟","هل يمكن تجديد مدة التدريب؟","كم شهر بقدر أتدرب بالجامعة؟"),
("number",[1],"تاسعاً وعاشراً","تحدد رسوم التدريب على النحو التالي: (100) دينار عن كل شهر تدريب على الأعمال الفنية أو المهنية أو الحرفية، و(50) ديناراً عن كل شهر تدريب على الأعمال الإدارية. ويلتزم المتدرب بدفع رسوم التدريب مقدماً عند الموافقة عن كل شهر من شهور التدريب.",
 "كم رسوم التدريب الشهرية على الأعمال الفنية والمهنية للمتدرب من غير العاملين؟","كم رسوم التدريب الشهرية على الأعمال الإدارية؟","قديش رسوم التدريب بالجامعة؟"),
("rule",[1],"حادي عشر إلى ثامن عشر","لا يحق للمتدرب المطالبة بالتعيين بالجامعة مستنداً لفترة التدريب، ويعتبر المتدرب منسحباً من التدريب إذا تغيب ثلاثة أيام متتالية دون عذر رسمي ولا يرد له مبلغ بدل التدريب أو أي جزء منه، ويلتزم المتدرب بالتوقيع على سجل الدوام اليومي الخاص بالحضور والمغادرة.",
 "هل يحق للمتدرب المطالبة بالتعيين بالجامعة بعد التدريب؟","متى يعتبر المتدرب منسحباً من التدريب؟","اذا تغيبت 3 أيام عن التدريب شو بصير؟"),
])

S('0241',"أسس انتقال الطلبة بين الجامعات الأردنية الرسمية على البرنامج العادي إلى جامعة العلوم والتكنولوجيا الأردنية لسنة 2017",[
("rule",[1],"المادة 2","يشترط في الطالب الراغب بالانتقال من إحدى الجامعات الرسمية الأردنية إلى جامعة العلوم والتكنولوجيا الأردنية: أن يكون الطالب مقبولاً ضمن القوائم الصادرة عن وحدة التنسيق الموحد في وزارة التعليم العالي، وأن تنطبق عليه حالة من حالات الانتقال: أن يكون قد أصيب بأحد الأمراض خلال فترة دراسته في الجامعة المراد الانتقال منها (مرض السرطان قيد العلاج الكيماوي أو الإشعاعي، والفشل الكلوي المزمن الذي يستدعي غسيلاً منتظماً، وأمراض الدماغ والأعصاب التي تؤدي إلى شلل جزئي أو كلي يعيق الحركة)، وأن يقدم مبررات مقنعة وتقارير طبية مصدقة وموافق عليها من اللجنة الطبية العليا في الجامعة ومجلس العمداء.",
 "ما شروط انتقال الطالب من جامعة أردنية رسمية إلى جامعة العلوم والتكنولوجيا على البرنامج العادي؟","في أي الحالات المرضية يسمح بالانتقال إلى الجامعة من جامعة رسمية أخرى؟","بقدر أنتقل من جامعة رسمية لجامعتكم بسبب مرضي؟"),
("rule",[1],"المادة 3","ينظر في انتقال الطالب إلى الجامعة من إحدى الجامعات الرسمية إذا كان متأثراً بإحدى القضايا العشائرية التي تستدعي الجلوة، ويكون الانتقال في هذه الحالة مؤقتاً لمدة فصل دراسي واحد قابل للتجديد، على أن يقدم الطالب كتاباً من الحاكم الإداري في اللواء يفيد بأن الطالب من الأشخاص المشمولين بالجلوة العشائرية.",
 "هل يسمح بانتقال الطالب بسبب قضية عشائرية؟","كم مدة الانتقال المؤقت للطالب المشمول بالجلوة العشائرية؟","انتقل بسبب جلوة عشائرية، كم مدة الانتقال؟"),
])

